package com.bank.mailinglist;

import java.util.*;
import java.util.logging.*;

public class ToSetDemo {
    private static final Logger log = Logger.getLogger("MailingList");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh"), new Employee("Priya"),
            new Employee("Rajesh"));  // duplicate name
        MailingListService service = new MailingListService();

        Set<String> names = service.distinctNames(staff);
        log.info(() -> "Distinct names: " + names + " (size=" + names.size() + ")");
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/MailingListService.java ───
class MailingListService {
    Set<String> distinctNames(List<Employee> staff) {
        return staff.stream()
            .map(Employee::getName)
            .collect(java.util.stream.Collectors.toSet());   // Set auto-dedupes
    }
}
